const securityChecks = [{"reportId": 1, "query": "SELECT pid, port, protocol, address FROM listening_ports WHERE pid != 0 AND port NOT IN (80,443,5678,1337,3000,3001,4200,5432,6379,3306) ORDER BY port", "description": "Puertos inusuales abiertos", "category": "red"}, {"reportId": 7, "query": "SELECT name, display_name, status, start_type, path FROM services WHERE start_type='auto' AND status='stopped' LIMIT 20", "description": "Servicios criticos detenidos", "category": "servicios"}, {"reportId": 8, "query": "SELECT name, action, path FROM scheduled_tasks WHERE enabled=1 AND (action LIKE '%wscript%' OR action LIKE '%cscript%' OR action LIKE '%powershell%')", "description": "Tareas programadas sospechosas", "category": "amenazas"}, {"reportId": 9, "query": "SELECT name, vendor, model, serial FROM usb_devices", "description": "Dispositivos USB conectados", "category": "hardware"}, {"reportId": 10, "query": "SELECT firewall, antivirus, autoupdate FROM windows_security_center", "description": "Estado de seguridad Windows", "category": "seguridad"}, {"reportId": 11, "query": "SELECT name, version, publisher FROM programs WHERE name LIKE '%AnyDesk%' OR name LIKE '%TeamViewer%' OR name LIKE '%Chrome Remote%' OR name LIKE '%ngrok%'", "description": "Herramientas de acceso remoto", "category": "amenazas"}, {"reportId": 12, "query": "SELECT pid, name, path, cmdline FROM processes WHERE (name LIKE '%netcat%' OR name LIKE '%nc.exe%' OR name LIKE '%ncat%' OR name LIKE '%socat%' OR cmdline LIKE '%reverse%shell%')", "description": "Procesos de acceso no autorizado", "category": "amenazas"}, {"reportId": 13, "query": "SELECT pid, name, path, cmdline FROM processes WHERE cmdline LIKE '%curl%http%' OR cmdline LIKE '%wget%http%' OR cmdline LIKE '%Invoke-WebRequest%'", "description": "Procesos descargando contenido", "category": "amenazas"}, {"reportId": 14, "query": "SELECT name, version, publisher FROM programs WHERE name LIKE '%7-Zip%' OR name LIKE '%WinRAR%' OR name LIKE '%WinZip%' OR name LIKE '%PeaZip%'", "description": "Herramientas de compresion", "category": "software"}, {"reportId": 15, "query": "SELECT name, version, publisher FROM programs WHERE name LIKE '%PuTTY%' OR name LIKE '%WinSCP%' OR name LIKE '%FileZilla%' OR name LIKE '%CyberDuck%'", "description": "Clientes FTP/SSH instalados", "category": "software"}, {"reportId": 16, "query": "SELECT user, tty, pid, uid, host, time FROM logged_in_users WHERE type='remote'", "description": "Sesiones remotas activas", "category": "usuarios"}, {"reportId": 17, "query": "SELECT destination, netmask, gateway, flags, interface FROM routes WHERE destination != '0.0.0.0' AND destination != '127.0.0.0' AND gateway != ''", "description": "Tabla de rutas de red", "category": "red"}, {"reportId": 18, "query": "SELECT interface, address, mask, broadcast, mac FROM interface_addresses WHERE interface != 'lo' AND address != '127.0.0.1'", "description": "Interfaces de red activas", "category": "red"}, {"reportId": 19, "query": "SELECT device_id, protection_status, encryption_method, percentage_encrypted FROM bitlocker_info", "description": "Estado de cifrado de disco", "category": "seguridad"}, {"reportId": 20, "query": "SELECT hostname, hardware_vendor, hardware_model, hardware_serial FROM system_info", "description": "Informacion del hardware", "category": "hardware"}, {"reportId": 21, "query": "SELECT name, version, build, platform FROM os_version", "description": "Version del sistema operativo", "category": "sistema"}, {"reportId": 22, "query": "SELECT uid, gid, username, description, directory, shell FROM users WHERE uid >= 1000", "description": "Usuarios del sistema", "category": "usuarios"}, {"reportId": 23, "query": "SELECT name, display_name, status, start_type, path FROM services WHERE status='running' AND path NOT LIKE 'C:\\Windows%' AND path NOT LIKE 'C:\\Program Files%' LIMIT 20", "description": "Servicios no estandar en ejecucion", "category": "amenazas"}, {"reportId": 24, "query": "SELECT pid, name, path, cmdline, user FROM processes WHERE user != 'NT AUTHORITY\\SYSTEM' AND user != 'NT AUTHORITY\\LOCAL SERVICE' AND user != 'NT AUTHORITY\\NETWORK SERVICE' ORDER BY phys_footprint DESC LIMIT 20", "description": "Procesos de usuario con mas memoria", "category": "procesos"}, {"reportId": 25, "query": "SELECT name, version, publisher, install_location FROM programs WHERE install_location LIKE '%temp%' OR install_location LIKE '%AppData%Local%Temp%'", "description": "Software en carpetas temporales", "category": "amenazas"}];
