const token = $('Prepare Security Checks').first().json.token;
const hostIds = $input.first().json.hosts.filter(h => h.status === 'online').map(h => ({ id: h.id, hostname: h.hostname }));
const allChecks = $('Prepare Security Checks').first().json.securityChecks;
const maxChecksPerRun = 4;
const chunkCount = Math.ceil(allChecks.length / maxChecksPerRun);
const chunkIndex = Math.floor(Date.now() / (30 * 60 * 1000)) % chunkCount;
const checks = allChecks.slice(chunkIndex * maxChecksPerRun, (chunkIndex + 1) * maxChecksPerRun);
const results = [];

for (const check of checks) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `https://fleet:1337/api/v1/fleet/reports/${check.reportId}`,
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: { query: check.query },
      json: true
    });

    const result = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://fleet:1337/api/v1/fleet/reports/${check.reportId}/run`,
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: { host_ids: hostIds.map(h => h.id) },
      json: true
    });

    results.push({
      json: {
        description: check.description,
        category: check.category,
        query: check.query,
        result: result,
        hostnames: hostIds.map(h => h.hostname),
        monitor_chunk: { index: chunkIndex + 1, total: chunkCount, checked: checks.length, total_checks: allChecks.length }
      }
    });
  } catch (error) {
    results.push({
      json: {
        description: check.description,
        category: check.category,
        error: error.message,
        monitor_chunk: { index: chunkIndex + 1, total: chunkCount, checked: checks.length, total_checks: allChecks.length }
      }
    });
  }
}

return results;

const items = $input.all();
const alerts = [];

for (const item of items) {
  const data = item.json;

  if (data.error) {
    alerts.push({
      json: {
        dispositivo: 'Sistema',
        mensaje: `Error en check "${data.description}": ${data.error}`,
        severidad: 'info',
        timestamp: new Date().toISOString(),
        raw: data
      }
    });
    continue;
  }

  const result = data.result;
  if (!result || !result.results) continue;

  for (const hostResult of result.results) {
    if (hostResult.rows && hostResult.rows.length > 0) {
      const hostname = data.hostnames?.find((h, i) => {
        const hostId = result.results.indexOf(hostResult);
        return true;
      }) || 'Desconocido';

      let severidad = 'low';
      if (data.category === 'amenazas') severidad = 'critical';
      else if (data.category === 'servicios') severidad = 'high';
      else if (data.category === 'red') severidad = 'medium';

      alerts.push({
        json: {
          dispositivo: hostname,
          mensaje: `${data.description}: ${hostResult.rows.length} hallazgo(s) detectado(s) en ${hostname}`,
          severidad: severidad,
          timestamp: new Date().toISOString(),
          raw: { check: data.description, category: data.category, rows: hostResult.rows.slice(0, 5) }
        }
      });
    }
  }
}

if (alerts.length === 0) {
  alerts.push({
    json: {
      dispositivo: 'Sistema',
      mensaje: 'Monitoreo completado: Sin anomalías detectadas en esta ronda.',
      severidad: 'info',
      timestamp: new Date().toISOString(),
      raw: { checks: items.length }
    }
  });
}

return alerts;

// Map LLM output to backend format
const items = $input.all();
return items.map(item => {
  const aiMessage = item.json.text || item.json.output || item.json.response || 'Alerta generada sin detalles';
  const prev = $('Analyze Results').first().json;

  return {
    json: {
      dispositivo: prev.dispositivo || 'Sistema',
      mensaje: aiMessage,
      severidad: prev.severidad || 'info',
      timestamp: new Date().toISOString(),
      raw: prev.raw || {}
    }
  };
});
